  slug: "pages",
  admin: {
    useAsTitle: "title",
    defaultColumns: ["title", "slug", "publishedAt"],
    preview: (doc) => {
      if (!doc.slug) return "";
      const slug = typeof doc.slug === "string" ? doc.slug : "";
      return `${BASE_URL}/preview/pages/${slug}`;
    },
  },
  access: {
    read: () => true,
  },
  fields: [
    {
      name: "title",
      type: "text",
      required: true,
      admin: {
        description: "The title of the page",
      },
    },
    {
      name: "slug",
      type: "text",
      required: true,
      unique: true,
      admin: {
        description: "The URL-friendly slug for the page (e.g., 'about-us')",
      },
    },
    {
      name: "meta",
      type: "group",
      fields: [
        {
          name: "title",
          type: "text",
          admin: {
            description: "Override the default meta title",
          },
        },
        {
          name: "description",
          type: "textarea",
          admin: {
            description: "Brief description for search engines",
          },
        },
        {
          name: "image",
          type: "upload",
          relationTo: "media",
          admin: {
            description: "Social sharing image",
          },
