interface ThemeToggleAnimatedProps {
  className?: string;
  variant?: ThemeToggleVariant;
  animationVariant?: AnimationVariant;
  animationStart?: AnimationStart;
  blur?: boolean;
}

export const ThemeToggleAnimated = ({
  className = "",
  variant = "yin-yang",
  animationVariant = "circle",
  animationStart = "center",
  blur = false,
}: ThemeToggleAnimatedProps) => {
  const { isDark, toggleTheme, canToggle } = useThemeToggle({
    variant: animationVariant,
    start: animationStart,
    blur,
  });

  switch (variant) {
    case "yin-yang":
      return (
        <ThemeToggleYinYang
          className={className}
          isDark={isDark}
          onToggle={toggleTheme}
          disabled={!canToggle}
        />
      );
    case "sun-moon":
      return (
        <ThemeToggleSunMoon
          className={className}
          isDark={isDark}
          onToggle={toggleTheme}
          disabled={!canToggle}
        />
      );
    case "sun-dots":
      return (
        <ThemeToggleSunDots
          className={className}
          isDark={isDark}
          onToggle={toggleTheme}
          disabled={!canToggle}
        />
      );
    case "lightbulb":
      return (
        <ThemeToggleLightbulb
          className={className}
          isDark={isDark}
          onToggle={toggleTheme}
          disabled={!canToggle}
        />
      );
    case "eclipse":
      return (
        <ThemeToggleEclipse
          className={className}
          isDark={isDark}
          onToggle={toggleTheme}
          disabled={!canToggle}
        />
      );
    default:
      return (
        <ThemeToggleYinYang
          className={className}
          isDark={isDark}
          onToggle={toggleTheme}
          disabled={!canToggle}
        />
      );
  }
};

